  Widget _buildActionsTab(
    DocumentoDoc doc,
    VersionDoc? currentVersion,
    String? rolDocumental,
  ) {
    final currentVersionId = currentVersion?.versionId;
    final canEnviar = currentVersionId != null &&
        GdRoles.puedeEjecutar('enviar_revision', rolDocumental);
    final canObservar = currentVersionId != null &&
        GdRoles.puedeEjecutar('observar', rolDocumental);
    final canReenviar = currentVersionId != null &&
        GdRoles.puedeEjecutar('reenviar', rolDocumental);
    final canAprobar = currentVersionId != null &&
        GdRoles.puedeEjecutar('aprobar', rolDocumental);
    final canFirmar = currentVersionId != null &&
        GdRoles.puedeEjecutar('firmar', rolDocumental);
    final canMarcarVigente = currentVersionId != null &&
        GdRoles.puedeEjecutar('marcar_vigente', rolDocumental);
    final canNuevaVersion =
        GdRoles.puedeEjecutar('nueva_version', rolDocumental);

    return ListView(
      padding: const EdgeInsets.all(24),
      children: [
        const Text(
          'Flujo de Aprobacion',
          style: TextStyle(
            fontFamily: kArial,
            fontWeight: FontWeight.w900,
            fontSize: 16,
            color: GdPalette.primary,
          ),
        ),
        const SizedBox(height: 20),
        if (doc.estado == GdEstado.borrador && canEnviar)
          _buildActionButton(
            label: 'ENVIAR A REVISION',
            icon: Icons.send,
            onPressed: () => _handleAction(
              () => _service.enviarARevision(
                docId: doc.docId,
                versionId: currentVersionId!,
                empresaId: widget.empresaId,
                actorId: widget.userId,
                rolDocumental: rolDocumental!,
              ),
            ),
          ),
        if (doc.estado == GdEstado.en_revision && canAprobar)
          _buildActionButton(
            label: 'APROBAR FORMALMENTE',
            icon: Icons.verified,
            color: GdPalette.success,
            onPressed: () => _handleAction(
              () => _service.aprobar(
                docId: doc.docId,
                versionId: currentVersionId!,
                empresaId: widget.empresaId,
                actorId: widget.userId,
                rolDocumental: rolDocumental!,
              ),
            ),
          ),
        if (doc.estado == GdEstado.en_revision && canAprobar && canObservar)
          const SizedBox(height: 12),
        if (doc.estado == GdEstado.en_revision && canObservar)
          _buildActionButton(
            label: 'OBSERVAR / RECHAZAR',
            icon: Icons.rule,
            color: GdPalette.warning,
            onPressed: () =>
                _showObservationDialog(doc, currentVersionId!, rolDocumental!),
          ),
        if (doc.estado == GdEstado.observado && canReenviar)
          _buildActionButton(
            label: 'REENVIAR A REVISION',
            icon: Icons.refresh,
            onPressed: () => _handleAction(
              () => _service.reenviar(
                docId: doc.docId,
                versionId: currentVersionId!,
                empresaId: widget.empresaId,
                actorId: widget.userId,
                rolDocumental: rolDocumental!,
              ),
            ),
          ),
        if (doc.estado == GdEstado.aprobado && canFirmar)
          _buildActionButton(
            label: 'FIRMAR INTERNAMENTE',
            icon: Icons.draw,
            color: GdPalette.success,
            onPressed: () => _handleAction(
              () => _service.firmar(
                docId: doc.docId,
                versionId: currentVersionId!,
                empresaId: widget.empresaId,
                actorId: widget.userId,
                rolDocumental: rolDocumental!,
              ),
            ),
          ),
        if (doc.estado == GdEstado.firmado && canMarcarVigente)
          _buildActionButton(
            label: 'MARCAR COMO VIGENTE',
            icon: Icons.public,
            color: GdPalette.primary,
            onPressed: () => _handleAction(
              () => _service.marcarVigente(
