    return Scaffold(
      backgroundColor: GdPalette.background,
      appBar: AppBar(
        title: const Text('Mi Identidad Digital', 
          style: TextStyle(fontFamily: kArial, fontWeight: FontWeight.w900, fontSize: 18)),
