class GdStatusBadge extends StatelessWidget {
  final GdEstado estado;
  final bool isVigente;

  const GdStatusBadge({
    super.key,
    required this.estado,
    this.isVigente = false,
  });

  @override
  Widget build(BuildContext context) {
    Color bg;
    Color text;
    IconData icon;

    if (isVigente) {
      bg = GdPalette.primary;
      text = Colors.white;
      icon = Icons.verified;
    } else {
      switch (estado) {
        case GdEstado.borrador:
          bg = GdPalette.muted.withOpacity(0.1);
          text = GdPalette.muted;
          icon = Icons.edit_note;
          break;
        case GdEstado.en_revision:
          bg = GdPalette.accent.withOpacity(0.1);
          text = GdPalette.accent;
          icon = Icons.visibility;
          break;
        case GdEstado.observado:
          bg = GdPalette.warning.withOpacity(0.1);
          text = GdPalette.warning;
          icon = Icons.rule;
          break;
        case GdEstado.aprobado:
          bg = GdPalette.success.withOpacity(0.1);
          text = GdPalette.success;
          icon = Icons.check_circle_outline;
          break;
        case GdEstado.firmado:
          bg = GdPalette.success.withOpacity(0.2);
          text = GdPalette.success;
          icon = Icons.draw;
          break;
        case GdEstado.vigente:
          bg = GdPalette.primary;
          text = Colors.white;
          icon = Icons.verified;
          break;
        case GdEstado.obsoleto:
          bg = GdPalette.muted.withOpacity(0.05);
          text = GdPalette.muted;
          icon = Icons.history;
          break;
      }
    }

    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
      decoration: BoxDecoration(
        color: bg,
        borderRadius: BorderRadius.circular(20),
        border: Border.all(color: text.withOpacity(0.2)),
      ),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          Icon(icon, size: 14, color: text),
          const SizedBox(width: 6),
          Text(
            isVigente ? 'VIGENTE' : estado.etiqueta.toUpperCase(),
            style: TextStyle(
              fontFamily: kArial,
              fontSize: 10,
              fontWeight: FontWeight.w900,
              color: text,
              letterSpacing: 0.5,
            ),
          ),
        ],
      ),
    );
  }
}

