      case GdAccion.observado:
      case GdAccion.marcado_obsoleto:
        return GdPalette.error;
      case GdAccion.enviado_revision:
      case GdAccion.reenviado:
        return GdPalette.accent;
      default:
        return GdPalette.muted;
    }
  }
}



